def main():
    # Finalized author/release text is deliberately not regenerated by the
    # original pre-approval report template below.
    authorization=C.DOC/'PUBLICATION_AUTHORIZATION.json'
    if authorization.exists() and C.read(authorization)['status']=='USER_AUTHORIZED':
        results=C.read(C.DOC/'WOOD_RESULTS.json');audit=C.read(C.DOC/'MATERIAL_PAPER_AUDIT.json')
        public=C.read(C.DOC/'PUBLIC_RESULTS.json')
        assert public['groups']==results['groups']
        C.save(C.DOC/'PUBLIC_FINAL_AUDIT.json',dict(status=audit['status'],checks=audit['checks'],tests_passed=audit['tests_passed'],
            publication_scope='Authorized reproducibility metadata, figures and manuscript; original RGB, coordinate arrays, camera matrices and weights excluded',
            PDF_pages=13,PDF_visual_review_pages=[1,5,6],raw_RGB_or_coordinate_arrays_published=False))
        print('AUTHORIZED_PUBLIC_AGGREGATES_VERIFIED; finalized prose preserved',flush=True)
        return
    results=C.read(C.DOC/'WOOD_RESULTS.json');decision=C.read(C.DOC/'MATERIAL_FINAL_DECISION.json')
    audit=C.read(C.DOC/'MATERIAL_PAPER_AUDIT.json')
