    C.save(C.DOC/'PUBLIC_RESULTS.json',dict(material_decision=decision['material_decision'],
        groups=results['groups'],severity_available=results['severity_available'],
        Q1_WOOD=results['Q1_WOOD'],frames=45,recordings=2,
        legacy_teacher_quality_not_verified=True,independent_confirmation=False,
        new_fits=2,updates_per_fit=320,train_unique=361,accepted_shared=676,candidates=1000))
